/* Meal photos, keyed by data-photo. Loaded by index.html. */
(function(){var P={
 "oct10-1": "data:image/jpeg;base64,",
 "oct10-2": "data:image/jpeg;base64,",
 "oct10-3": "data:image/jpeg;base64,",
 "oct10-4": "data:image/jpeg;base64,",
 "oct11-1": "data:image/jpeg;base64,",
 "oct11-2": "data:image/jpeg;base64,",
 "oct11-3": "data:image/jpeg;base64,",
 "oct12-1": "data:image/jpeg;base64,",
 "oct12-2": "data:image/jpeg;base64,",
 "oct12-3": "data:image/jpeg;base64,",
 "oct13-1": "data:image/jpeg;base64,",
 "oct13-2": "data:image/jpeg;base64,",
 "oct13-3": "data:image/jpeg;base64,",
 "oct13-4": "data:image/jpeg;base64,"
};
function go(){document.querySelectorAll("img[data-photo]").forEach(function(i){var d=P[i.getAttribute("data-photo")];if(d)i.src=d;});}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",go);else go();})();
